/* Local-first quiz application. Do not put real credentials or sensitive production data here. */
const QUIZ_CONFIG={totalQuestions:40,marksPerQuestion:1,totalMarks:40,durationMinutes:60,negativeMarking:0,randomizeQuestions:true,randomizeOptions:true,allowQuestionRepeat:false,autoSubmit:true};
const KEYS={students:'kleBcaStudents',results:'kleBcaResults',questions:'kleBcaQuestionBank',current:'kleBcaCurrentQuiz',admin:'kleBcaAdmin'};
const CLASSES=['BCA 1st Year','BCA 2nd Year','BCA 3rd Year'];
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const read=(key,fallback=[])=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const write=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));return true}catch{alert('Your browser could not save this data. Check available storage and try again.');return false}};
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fisherYates=array=>{const out=[...array];for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]]}return out};
const questions=()=>read(KEYS.questions,[]), students=()=>read(KEYS.students,[]), results=()=>read(KEYS.results,[]), current=()=>read(KEYS.current,null);
const saveQuestions=list=>{if(!write(KEYS.questions,list))return false;if(sessionStorage.getItem('kleBcaAdminSession')&&!isLocalPreviewAdmin()){const payload=JSON.stringify({questions:list});questionSyncQueue=questionSyncQueue.then(async()=>{try{const response=await fetch('/api/questions',{method:'PUT',credentials:'same-origin',headers:{'content-type':'application/json'},body:payload}),body=await response.json();if(!response.ok)throw new Error(body.error||'Question bank could not be shared.');}catch(error){alert(`Questions were saved on this device but not shared with students: ${error.message}`)}})}return true};
let quizIndex=0,timerHandle=null,adminRefreshTimer=null,adminRefreshInFlight=false,resultSyncTimer=null,resultSyncInFlight=false,questionSyncQueue=Promise.resolve(),importedPdfQuestions=[],studyBackgroundTimer=null,pdfJsModulePromise=null;
const STUDY_BACKGROUNDS=['assets/illustrations/page-background.svg','assets/illustrations/study-books-background.svg','assets/illustrations/study-formulas-background.svg','assets/illustrations/study-graduation-background.svg'];
function startStudyBackgroundSlider(){const slides=$$('#study-background .study-background-slide');if(!slides.length)return;const motion=matchMedia('(prefers-reduced-motion: reduce)'),images=STUDY_BACKGROUNDS.map(src=>{const image=new Image();image.src=src;image.addEventListener('error',()=>console.warn(`Study background could not be loaded: ${src}`),{once:true});return image});slides.forEach((slide,index)=>slide.style.setProperty('--slide-image',`url("${images[index%images.length].src}")`));let active=0;const rotate=()=>{if(document.visibilityState==='hidden')return;slides[active].classList.remove('is-active');active=(active+1)%slides.length;slides[active].classList.add('is-active')};const start=()=>{if(!studyBackgroundTimer)studyBackgroundTimer=setInterval(rotate,2000)};if(!motion.matches)start();motion.addEventListener('change',event=>{if(event.matches){clearInterval(studyBackgroundTimer);studyBackgroundTimer=null}else start()})}
function dateText(timestamp){return timestamp?new Date(timestamp).toLocaleDateString():'—'}function timeText(timestamp){return timestamp?new Date(timestamp).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}):'—'}
function showView(id){$$('.view').forEach(v=>v.classList.toggle('hidden',v.id!==id));$('#learning-showcase')?.classList.toggle('hidden',id!=='home');if(location.hash!==`#${id}`)history.replaceState(null,'',`#${id}`);if(id==='home')readiness();if(id==='admin'){void loadAdminData();startAdminAutoRefresh()}else stopAdminAutoRefresh();if(id==='quiz')renderQuiz();if(id==='result')renderResult();if(id==='review')renderReview();window.scrollTo(0,0)}
function readiness(){const verified=questions().filter(q=>q.verified&&q.enabled!==false&&q.correctOptionId&&q.options?.length===4).length;const box=$('#question-readiness');box.className='readiness notice '+(verified>=40?'':'warning');box.textContent=verified>=40?`Quiz Ready · ${verified} verified questions available`:`Quiz unavailable · ${verified}/40 verified questions. Please contact the administrator.`}
function route(){let id=location.hash.slice(1)||'home';if(id==='quiz'&&!current()){id='register'}if(id==='admin'&&!sessionStorage.getItem('kleBcaAdminSession'))id='admin-login';if(!$('#'+id))id='home';showView(id)}
window.addEventListener('hashchange',route);window.addEventListener('online',()=>void syncPendingResults());document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&location.hash==='#admin'&&!isLocalPreviewAdmin())void loadAdminData();if(document.visibilityState==='visible')void syncPendingResults()});document.addEventListener('DOMContentLoaded',async()=>{startStudyBackgroundSlider();resultSyncTimer=setInterval(()=>{if(document.visibilityState==='visible'&&results().some(result=>result.syncStatus!=='synced'))void syncPendingResults()},30000);$('#refresh-admin').addEventListener('click',()=>void loadAdminData());const menu=$('.menu-toggle');menu.addEventListener('click',()=> $('nav').classList.toggle('open'));$$('nav a').forEach(a=>a.addEventListener('click',()=>$('nav').classList.remove('open')));$('#registration-form').addEventListener('submit',registerStudent);$('#agree-instructions').addEventListener('change',e=>$('#start-quiz').disabled=!e.target.checked);$('#start-quiz').addEventListener('click',startQuiz);$('#previous-question').addEventListener('click',()=>moveQuestion(-1));$('#next-question').addEventListener('click',()=>moveQuestion(1));$('#submit-quiz').addEventListener('click',()=>confirmSubmit(false));$('#login-form').addEventListener('submit',login);$('#admin-logout').addEventListener('click',async()=>{if(!isLocalPreviewAdmin())await fetch('/api/admin/logout',{method:'POST',credentials:'same-origin'}).catch(()=>{});sessionStorage.removeItem('kleBcaAdminSession');sessionStorage.removeItem('kleBcaLocalAdminSession');showView('admin-login')});$$('.tab').forEach(b=>b.addEventListener('click',()=>selectTab(b.dataset.tab)));$('#add-question').addEventListener('click',()=>questionEditor());$('#question-search').addEventListener('input',renderQuestions);$('#question-filter').addEventListener('change',renderQuestions);$('#student-search').addEventListener('input',renderStudents);$('#class-filter').addEventListener('change',renderStudents);$('#semester-filter').addEventListener('change',renderStudents);$('#student-sort').addEventListener('change',renderStudents);await seedQuestionBank();route();void syncPendingResults()});
async function seedQuestionBank(){try{let response=await fetch('/api/questions',{cache:'no-store'}),shared=response.ok;if(!shared)response=await fetch('data/questions.json');if(!response.ok)throw new Error('Question bank unavailable');const bank=await response.json(),existing=read(KEYS.questions,[]),byId=new Map(existing.map(q=>[q.id,q]));if(shared){const savedById=new Map(existing.map(q=>[q.id,q]));for(const source of bank.questions||[]){const saved=savedById.get(source.id);if(saved?.enabled===false)source.enabled=false}if(write(KEYS.questions,bank.questions||[]))localStorage.setItem('kleBcaSourceSeeded','true');return}for(const source of bank.questions||[]){const saved=byId.get(source.id);if(!saved){existing.push(source);continue}if(!saved.verified&&source.verified){saved.correctOptionId=source.correctOptionId;saved.explanation=source.explanation;saved.verified=true;saved.verificationMethod=source.verificationMethod}if(source.enabled===false&&!source.verified){saved.enabled=false;saved.explanation=source.explanation;saved.verificationMethod=source.verificationMethod}}if(write(KEYS.questions,existing))localStorage.setItem('kleBcaSourceSeeded','true')}catch{if(!Array.isArray(read(KEYS.questions,null)))write(KEYS.questions,[]);$('#question-readiness').textContent='Question bank could not be loaded. Please contact the administrator and refresh.'}}
function isLocalPreviewHost(){return ['localhost','127.0.0.1','[::1]'].includes(location.hostname)}
async function syncStudentRecord(student,status,attemptId=null){let response;try{response=await fetch('/api/students',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({...student,status,attemptId})})}catch(error){if(isLocalPreviewHost())return;throw error}try{await apiJson(response,'Could not save this student to the shared admin records.')}catch(error){if(isLocalPreviewHost()&&apiError(response))return;throw error}}
async function registerStudent(event){event.preventDefault();const form=new FormData(event.target),registrationNumber=String(form.get('registrationNumber')||'').trim(),name=String(form.get('name')||'').trim(),semester=form.get('semester'),className=form.get('className'),error=$('#register-error');error.classList.add('hidden');if(!registrationNumber){error.textContent='Please enter your registration number.';error.classList.remove('hidden');return}if(!name){error.textContent='Please enter your name.';error.classList.remove('hidden');return}if(!semester){error.textContent='Please select your semester.';error.classList.remove('hidden');return}if(!className){error.textContent='Please select your class.';error.classList.remove('hidden');return}const active=current();if(active&&!active.submitted){error.textContent='A quiz attempt is already active in this browser. Resume it before registering another student.';error.classList.remove('hidden');return}const match=registrationNumber.toLowerCase(),existing=students().find(s=>s.registrationNumber.toLowerCase()===match);if(existing&&(existing.status!=='Registered'||results().some(r=>r.student.registrationNumber.toLowerCase()===match))){error.textContent='This registration number already has an active or completed attempt. Please contact the administrator.';error.classList.remove('hidden');return}const now=Date.now(),student={registrationNumber,name,semester,className,registrationTimestamp:existing?.registrationTimestamp||now,registrationDate:dateText(existing?.registrationTimestamp||now),registrationTime:timeText(existing?.registrationTimestamp||now),status:'Registered',attemptId:null};const all=students().filter(s=>s.registrationNumber.toLowerCase()!==match);all.push(student);if(!write(KEYS.students,all))return;try{await syncStudentRecord(student,'Registered')}catch(syncError){error.textContent=`${syncError.message} Please check your connection and try again; your quiz registration has not been confirmed.`;error.classList.remove('hidden');return}write('kleBcaPendingStudent',student);$('#instruction-error').classList.add('hidden');$('#agree-instructions').checked=false;$('#start-quiz').disabled=true;showView('instructions')}
async function startQuiz(){if(!$('#agree-instructions').checked)return;const student=read('kleBcaPendingStudent',null);if(!student){showView('register');return}const bank=questions().filter(q=>q.verified&&q.enabled!==false&&q.correctOptionId&&Array.isArray(q.options)&&q.options.length===4&&q.options.some(o=>o.id===q.correctOptionId));if(bank.length<40){const box=$('#instruction-error');box.textContent='Quiz cannot be started because fewer than 40 verified questions are available. Please contact the administrator.';box.classList.remove('hidden');return}const selected=fisherYates(bank).slice(0,40);if(selected.length!==40||new Set(selected.map(q=>q.id)).size!==40){alert('The question bank could not supply 40 unique questions. Contact the administrator.');return}const startTime=Date.now(),attemptId=`${student.registrationNumber}_${startTime}`,quiz={attemptId,student,questionIds:selected.map(q=>q.id),optionOrder:Object.fromEntries(selected.map(q=>[q.id,fisherYates(q.options).map(o=>o.id)])),answers:{},startTime,endTime:startTime+QUIZ_CONFIG.durationMinutes*60000,submitted:false};try{await syncStudentRecord(student,'Started',attemptId)}catch(error){const box=$('#instruction-error');box.textContent=`Could not record the assessment start: ${error.message}`;box.classList.remove('hidden');return}if(!write(KEYS.current,quiz))return;student.status='Started';student.attemptId=attemptId;write(KEYS.students,students().map(s=>s.registrationNumber===student.registrationNumber?student:s));quizIndex=0;showView('quiz')}
function activeQuestion(){const quiz=current();if(!quiz)return null;return questions().find(q=>q.id===quiz.questionIds[quizIndex])||null}
function renderQuiz(){const quiz=current();if(!quiz||quiz.submitted){if(quiz?.submitted)showView('result');else showView('register');return}$('#quiz-student').textContent=quiz.student.name;$('#quiz-identity').textContent=`${quiz.student.registrationNumber} · ${quiz.student.className} · ${quiz.student.semester}`;if(quizIndex<0)quizIndex=0;if(quizIndex>=quiz.questionIds.length)quizIndex=quiz.questionIds.length-1;const q=activeQuestion();if(!q){alert('A quiz question is missing. Your attempt is saved; contact the administrator.');return}$('#question-category').textContent=q.category||'General';$('#question-text').textContent=q.question;const answer=quiz.answers[q.id];$('#options').innerHTML=quiz.optionOrder[q.id].map((id,i)=>{const option=q.options.find(o=>o.id===id);if(!option)return '';return `<label class="option ${answer===id?'selected':''}"><input type="radio" name="answer" value="${esc(id)}" ${answer===id?'checked':''}><span><b>${String.fromCharCode(65+i)}.</b> ${esc(option.text)}</span></label>`}).join('');$$('#options input').forEach(input=>input.addEventListener('change',()=>storeAnswer(q.id,input.value)));$('#previous-question').disabled=quizIndex===0;$('#next-question').textContent=quizIndex===quiz.questionIds.length-1?'Last question':'Next →';$('#progress-label').textContent=`Question ${quizIndex+1} of ${quiz.questionIds.length}`;const answered=Object.keys(quiz.answers).length,percent=Math.round(answered/quiz.questionIds.length*100);$('#progress-percent').textContent=`${percent}% completed`;$('#progress-bar').style.width=`${percent}%`;$('#question-grid').innerHTML=quiz.questionIds.map((id,i)=>`<button class="q-button ${i===quizIndex?'current':''} ${quiz.answers[id]?'answered':''}" data-index="${i}" aria-label="Question ${i+1}${quiz.answers[id]?', answered':', unanswered'}">${i+1}</button>`).join('');$$('#question-grid button').forEach(b=>b.addEventListener('click',()=>{quizIndex=Number(b.dataset.index);renderQuiz()}));startTimer()}
function storeAnswer(questionId,optionId){const quiz=current();if(!quiz||quiz.submitted)return;quiz.answers[questionId]=optionId;write(KEYS.current,quiz);renderQuiz()}
function moveQuestion(delta){quizIndex=Math.max(0,Math.min(39,quizIndex+delta));renderQuiz()}
function startTimer(){if(timerHandle)clearInterval(timerHandle);const tick=()=>{const quiz=current();if(!quiz||quiz.submitted)return;const remaining=Math.max(0,quiz.endTime-Date.now()),seconds=Math.ceil(remaining/1000),mins=Math.floor(seconds/60),secs=seconds%60,timer=$('#timer'),warning=$('#timer-warning');timer.textContent=`${String(mins).padStart(2,'0')}:${String(secs).padStart(2,'0')}`;timer.classList.toggle('warning',remaining<=600000&&remaining>300000);timer.classList.toggle('urgent',remaining<=300000);warning.classList.toggle('hidden',remaining>600000);warning.textContent=remaining<=300000?'Only 5 minutes remaining.':remaining<=600000?'10 minutes remaining.':'';if(remaining<=0){clearInterval(timerHandle);confirmSubmit(true)}};tick();timerHandle=setInterval(tick,1000)}
function toast(message){const box=$('#instruction-error');box.textContent=message;box.classList.remove('hidden');setTimeout(()=>box.classList.add('hidden'),4500)}
function confirmSubmit(automatic){const quiz=current();if(!quiz||quiz.submitted)return;const unanswered=quiz.questionIds.length-Object.keys(quiz.answers).length;$('#modal-body').innerHTML=`<h2>${automatic?'Time is up':'Submit your quiz?'}</h2><p>${automatic?'Your quiz will now be submitted automatically.':'Are you sure you want to submit the quiz?'}</p><p>Answered: <b>${Object.keys(quiz.answers).length} / 40</b> · Unanswered: <b>${unanswered} / 40</b></p><div class="modal-actions">${automatic?'':'<button class="btn light" id="cancel-submit">Cancel</button>'}<button class="btn primary" id="confirm-submit">${automatic?'View Result':'Submit'}</button></div>`;$('#modal').classList.remove('hidden');$('#cancel-submit')?.addEventListener('click',()=>$('#modal').classList.add('hidden'));$('#confirm-submit').addEventListener('click',submitQuiz)}
async function submitQuiz(){const quiz=current();if(!quiz||quiz.submitted)return;const bank=questions(),counts={correctCount:0,wrongCount:0,unansweredCount:0};for(const id of quiz.questionIds){const q=bank.find(x=>x.id===id);if(!q){counts.unansweredCount++;continue}const answer=quiz.answers[id];if(!answer)counts.unansweredCount++;else if(answer===q.correctOptionId)counts.correctCount++;else counts.wrongCount++}const endTime=Math.min(Date.now(),quiz.endTime),score=counts.correctCount,result={...quiz,...counts,score,totalMarks:40,percentage:score/40*100,endTime,timeTakenMs:Math.max(0,endTime-quiz.startTime),quizDate:dateText(endTime),quizTime:timeText(endTime),status:'Completed',submitted:true};const all=results();if(!all.some(r=>r.attemptId===result.attemptId))all.push(result);result.syncStatus='pending';if(!write(KEYS.results,all))return;quiz.submitted=true;quiz.endTime=endTime;write(KEYS.current,quiz);write(KEYS.students,students().map(s=>s.registrationNumber===quiz.student.registrationNumber?{...s,status:'Completed'}:s));$('#modal').classList.add('hidden');if(timerHandle)clearInterval(timerHandle);try{await syncResultToServer(result)}catch(error){result.syncStatus='pending';write(KEYS.results,results().map(r=>r.attemptId===result.attemptId?result:r))}showView('result')}
async function syncResultToServer(result){const response=await fetch('/api/results',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify(result)});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||'The shared result service could not save this attempt.');const all=results(),index=all.findIndex(r=>r.attemptId===result.attemptId);if(index>=0)all[index]=body.result;else all.push(body.result);write(KEYS.results,all);const ss=students(),student=body.student||{...result.student,status:'Completed'};write(KEYS.students,[...ss.filter(s=>s.registrationNumber.toLowerCase()!==student.registrationNumber.toLowerCase()),student]);return body.result}
async function syncPendingResults(){if(resultSyncInFlight)return;resultSyncInFlight=true;try{for(const result of results().filter(r=>r.syncStatus!=='synced')){try{await syncResultToServer(result)}catch(error){console.warn('Result sync pending:',error.message)}}}finally{resultSyncInFlight=false}}
function renderResult(){const quiz=current(),result=results().find(r=>r.attemptId===quiz?.attemptId);if(!result){$('#result-content').innerHTML='<div class="panel">No completed result was found. <a href="#register">Register to begin</a>.</div>';return}$('#result-content').innerHTML=`<article class="panel result-card"><div class="result-top"><span class="eyebrow">KLE SOCIETY'S BCA COLLEGE, ANKALI</span><h1>Quiz Completed</h1><p>${esc(result.student.name)} · ${esc(result.student.registrationNumber)}</p><div class="score-circle"><b>${result.score}/40</b><span>${result.percentage}%</span></div></div><div class="result-facts"><div><b>${result.correctCount}</b>Correct answers</div><div><b>${result.wrongCount}</b>Wrong answers</div><div><b>${result.unansweredCount}</b>Unanswered</div><div><b>${esc(result.student.className)}</b>Class</div><div><b>${esc(result.student.semester)}</b>Semester</div><div><b>${formatDuration(result.timeTakenMs)}</b>Time taken</div><div><b>${esc(result.quizDate)}</b>Quiz date</div><div><b>${esc(result.quizTime)}</b>Quiz time</div><div><b>${esc(result.student.registrationNumber)}</b>Registration number</div></div><div id="result-sync-status" class="notice ${result.syncStatus==='pending'?'error':''}">${result.syncStatus==='pending'?'This result is saved on this device but has not reached the shared admin records yet. Check your internet connection and retry. <button class="btn light" id="retry-result-sync">Retry sync</button>':result.syncStatus==='synced'?'Result saved to the shared student records.':''}</div><div class="result-actions"><a class="btn primary" href="#review">Review Answers →</a><a class="btn light" href="#home">Back to Home</a></div></article>`;const retry=$('#retry-result-sync');retry?.addEventListener('click',async()=>{retry.disabled=true;try{await syncResultToServer(result);renderResult()}catch(error){retry.disabled=false;$('#result-sync-status').textContent=error.message||'Could not sync yet. Please try again.'}})}
function formatDuration(ms){const n=Math.floor(ms/1000);return `${Math.floor(n/60)}m ${n%60}s`}
function renderReview(){const quiz=current(),result=results().find(r=>r.attemptId===quiz?.attemptId);if(!result){$('#review-content').innerHTML='<div class="panel">Complete an attempt before reviewing answers.</div>';return}$('#review-content').innerHTML=result.questionIds.map((id,i)=>{const q=questions().find(x=>x.id===id),answer=result.answers[id],selected=q?.options.find(o=>o.id===answer)?.text||'Unanswered',correct=q?.options.find(o=>o.id===q.correctOptionId)?.text||'Not verified';const status=!answer?'unanswered':answer===q?.correctOptionId?'correct':'wrong';return `<article class="panel review-item ${status}"><span class="status-tag ${status==='correct'?'verified':''}">${status==='unanswered'?'Unanswered':status==='correct'?'Correct':'Wrong'}</span><h3>Question ${i+1}: ${esc(q?.question||'Question unavailable')}</h3><div class="review-answer"><span>Your answer: <strong>${esc(selected)}</strong></span><span>Correct answer: <strong>${esc(correct)}</strong></span></div></article>`}).join('')}
function apiError(response){if(response.status===404||response.status===405||!response.headers.get('content-type')?.includes('application/json'))return new Error('The Netlify API is unavailable. Use the deployed Netlify site or run `npx netlify-cli dev` from the project folder.');return null}
async function apiJson(response,fallback){const unavailable=apiError(response);if(unavailable)throw unavailable;let body;try{body=await response.json()}catch{throw new Error(fallback)}if(!response.ok)throw new Error(body.error||fallback);return body}
function isLocalPreviewAdmin(){return ['localhost','127.0.0.1','[::1]'].includes(location.hostname)&&sessionStorage.getItem('kleBcaLocalAdminSession')==='authenticated'}
function enterLocalPreviewAdmin(data){if(!['localhost','127.0.0.1','[::1]'].includes(location.hostname)||data.get('username')!=='admin'||data.get('password')!=='admin123')return false;sessionStorage.setItem('kleBcaLocalAdminSession','authenticated');sessionStorage.setItem('kleBcaAdminSession','authenticated');showView('admin');return true}
async function login(event){event.preventDefault();const form=event.currentTarget,data=new FormData(form),error=$('#login-error'),button=form.querySelector('button[type="submit"]'),label=button.textContent;button.disabled=true;button.textContent='Signing in…';sessionStorage.removeItem('kleBcaAdminSession');sessionStorage.removeItem('kleBcaLocalAdminSession');error.classList.add('hidden');try{let response;try{response=await fetch('/api/admin/login',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({username:data.get('username'),password:data.get('password')})})}catch(networkError){if(enterLocalPreviewAdmin(data))return;throw networkError}try{await apiJson(response,'Sign in failed.')}catch(apiFailure){if(apiError(response)&&enterLocalPreviewAdmin(data))return;throw apiFailure}const check=await fetch('/api/results',{credentials:'same-origin',cache:'no-store'});if(check.status===401)throw new Error('Credentials were accepted, but the admin session cookie was not retained. Use the HTTPS Netlify site or Netlify Dev and try again.');const body=await apiJson(check,'Could not verify the admin session. Please sign in again.');write(KEYS.results,body.results||[]);write(KEYS.students,body.students||[]);sessionStorage.setItem('kleBcaAdminSession','authenticated');showView('admin')}catch(e){error.textContent=e.message||'Admin service is unavailable. Try again later.';error.classList.remove('hidden')}finally{button.disabled=false;button.textContent=label}}
function selectTab(tab){$$('.tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$$('.tab-content').forEach(c=>c.classList.toggle('hidden',c.id!==`tab-${tab}`));if(tab==='questions')renderQuestions();if(tab==='students')renderStudents();if(tab==='classes')renderClasses()}
function renderAdmin(){if(!sessionStorage.getItem('kleBcaAdminSession')){showView('admin-login');return}const list=questions(),rs=results(),ss=students(),verified=list.filter(q=>q.verified&&q.enabled!==false).length,avg=rs.length?Math.round(rs.reduce((n,r)=>n+r.score,0)/rs.length*10)/10:0;$('#admin-readiness').className=`notice ${verified>=40?'':'warning'}`;$('#admin-readiness').textContent=verified>=40?`Quiz Ready · ${verified} verified questions`:`Quiz Not Ready · ${verified}/40 verified questions`;$('#dashboard-stats').innerHTML=[['Total Registered Students',ss.length],['Completed Quizzes',rs.length],['BCA 1st Year Students',ss.filter(s=>s.className===CLASSES[0]).length],['BCA 2nd Year Students',ss.filter(s=>s.className===CLASSES[1]).length],['BCA 3rd Year Students',ss.filter(s=>s.className===CLASSES[2]).length],['Average Score',`${avg}/40`],['Highest Score',`${rs.length?Math.max(...rs.map(r=>r.score)):0}/40`],['Verified Questions',`${verified}/40`]].map(([a,b])=>`<article><b>${esc(b)}</b><span>${esc(a)}</span></article>`).join('');renderQuestions();renderStudents();renderClasses();renderExports()}
function startAdminAutoRefresh(){if(adminRefreshTimer||isLocalPreviewAdmin())return;adminRefreshTimer=setInterval(()=>{if(document.visibilityState==='visible'&&location.hash==='#admin')void loadAdminData()},15000)}
function stopAdminAutoRefresh(){if(adminRefreshTimer){clearInterval(adminRefreshTimer);adminRefreshTimer=null}}
async function loadAdminData(){if(adminRefreshInFlight)return;if(isLocalPreviewAdmin()){renderAdmin();$('#admin-readiness').className='notice warning';$('#admin-readiness').textContent='Local preview mode: questions and results are stored only in this browser and are not shared.';return}adminRefreshInFlight=true;const refresh=$('#refresh-admin');if(refresh)refresh.disabled=true;try{await syncPendingResults();const response=await fetch('/api/results',{credentials:'same-origin',cache:'no-store'});if(response.status===401){sessionStorage.removeItem('kleBcaAdminSession');showView('admin-login');return}const body=await apiJson(response,'Unable to load shared results.');write(KEYS.results,body.results||[]);write(KEYS.students,body.students||[]);renderAdmin();$('#admin-readiness').textContent+=` · Updated ${new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'})}`}catch(error){renderAdmin();$('#admin-readiness').className='notice warning';$('#admin-readiness').textContent=error.message||'Shared results could not be loaded. Check your connection and reload this dashboard.'}finally{adminRefreshInFlight=false;if(refresh)refresh.disabled=false}}
function renderQuestions(){const filter=$('#question-filter').value,term=$('#question-search').value.toLowerCase();let qs=questions().filter(q=>(filter==='all'||(filter==='verified'?q.verified:!q.verified))&&(`${q.question} ${q.id} ${q.category}`.toLowerCase().includes(term)));$('#question-list').innerHTML=qs.length?qs.map(q=>`<article class="panel question-card"><span class="status-tag ${q.verified?'verified':''}">${q.verified?'Verified':'Not Verified'}${q.enabled===false?' · Disabled':''}</span><h3>${esc(q.question)}</h3><div class="question-options">${q.options.map((o,i)=>`<span>${String.fromCharCode(65+i)}. ${esc(o.text)} ${o.id===q.correctOptionId?'✓':''}</span>`).join('')}</div><p class="muted">Source question ${esc(q.sourceQuestionNumber||'—')} · ${esc(q.category||'General')}${q.verificationMethod?` · ${esc(q.verificationMethod)}`:''}</p><div class="question-actions"><span class="muted">${q.explanation?`Explanation: ${esc(q.explanation)}`:''}</span><span><button class="btn light" data-edit="${esc(q.id)}">Edit</button> <button class="btn light" data-toggle="${esc(q.id)}">${q.enabled===false?'Enable':'Disable'}</button> <button class="btn danger" data-delete="${esc(q.id)}">Delete</button></span></div></article>`).join(''):'<div class="panel">No questions yet. Add exact questions from the source paper to begin building the bank.</div>';$$('[data-edit]').forEach(b=>b.addEventListener('click',()=>questionEditor(b.dataset.edit)));$$('[data-toggle]').forEach(b=>b.addEventListener('click',()=>toggleQuestion(b.dataset.toggle)));$$('[data-delete]').forEach(b=>b.addEventListener('click',()=>deleteQuestion(b.dataset.delete)))}
function questionEditor(id){const q=id?questions().find(x=>x.id===id):null,opts=q?.options||[{id:'',text:''},{id:'',text:''},{id:'',text:''},{id:'',text:''}];$('#modal-body').innerHTML=`<h2>${q?'Edit question':'Add source question'}</h2><form id="question-form"><label>Exact question text<textarea name="question" required>${esc(q?.question||'')}</textarea></label><div class="form-grid">${opts.map((o,i)=>`<label>Option ${String.fromCharCode(65+i)}<input name="option${i}" value="${esc(o.text)}" required></label>`).join('')}</div><div class="form-grid"><label>Source question number<input name="sourceQuestionNumber" type="number" min="1" value="${esc(q?.sourceQuestionNumber||'')}"></label><label>Category<select name="category">${['General','English','General Knowledge','Computer Fundamentals','Programming','Data Structures','Mathematics','Statistics','Logical Reasoning','Database','Networking','Operating Systems'].map(c=>`<option ${q?.category===c?'selected':''}>${c}</option>`).join('')}</select></label></div><label>Explanation (optional)<textarea name="explanation">${esc(q?.explanation||'')}</textarea></label><p class="muted">Answer choices and verified status must be checked against the source paper. No official answer is assumed.</p><label>Correct option<select name="correct"><option value="">Not verified</option>${['A','B','C','D'].map((c,i)=>`<option value="${i}" ${q?.correctOptionId===opts[i]?.id?'selected':''}>${c}</option>`).join('')}</select></label><label class="check-row"><input type="checkbox" name="verified" ${q?.verified?'checked':''}> I have verified the exact question and correct answer against a reliable source</label><div class="modal-actions"><button type="button" id="close-editor" class="btn light">Cancel</button><button class="btn primary">Save question</button></div></form>`;$('#modal').classList.remove('hidden');$('#close-editor').addEventListener('click',()=>$('#modal').classList.add('hidden'));$('#question-form').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target),question=d.get('question').trim(),options=[0,1,2,3].map(i=>({id:opts[i].id||`${id||`q${Date.now()}`}_opt${i+1}`,text:d.get(`option${i}`).trim()})),correct=d.get('correct'),verified=d.get('verified')==='on';if(options.some(o=>!o.text)){alert('Enter all four options.');return}if(verified&&correct===''){alert('Select a correct option before marking this question verified.');return}const next={id:q?.id||`q${Date.now()}_${Math.random().toString(36).slice(2,7)}`,sourceQuestionNumber:Number(d.get('sourceQuestionNumber'))||null,question,options,correctOptionId:correct===''?null:options[Number(correct)].id,category:d.get('category'),image:null,explanation:d.get('explanation').trim()||null,verified,enabled:q?.enabled!==false};const list=questions();if(q){list[list.findIndex(x=>x.id===id)]=next}else list.push(next);if(saveQuestions(list)){$('#modal').classList.add('hidden');renderAdmin();readiness()}})}
function toggleQuestion(id){saveQuestions(questions().map(q=>q.id===id?{...q,enabled:q.enabled===false}:q));renderAdmin()}function deleteQuestion(id){if(!confirm('Delete this question from the bank?'))return;saveQuestions(questions().filter(q=>q.id!==id));renderAdmin()}
function renderStudents(){const term=$('#student-search').value.toLowerCase(),cls=$('#class-filter').value,sem=$('#semester-filter').value,sort=$('#student-sort').value,completed=results(),byRegistration=new Map(completed.map(result=>[result.student.registrationNumber.toLowerCase(),result])),rows=completed.map(result=>({student:result.student,result,attemptId:result.attemptId,date:result.quizDate}));for(const student of students()){if(!byRegistration.has(student.registrationNumber.toLowerCase()))rows.push({student,result:null,attemptId:null,date:student.registrationDate||dateText(student.registrationTimestamp)})}const filtered=rows.filter(row=>(cls==='all'||row.student.className===cls)&&(sem==='all'||row.student.semester===sem)&&(`${row.student.registrationNumber} ${row.student.name}`.toLowerCase().includes(term)));filtered.sort((a,b)=>sort==='score'?(b.result?.score??-1)-(a.result?.score??-1):(b.result?.endTime||b.student.registrationTimestamp||0)-(a.result?.endTime||a.student.registrationTimestamp||0));$('#student-table').innerHTML=`<div class="student-table-wrap"><table class="student-table"><thead><tr><th>Registration No.</th><th>Student Name</th><th>Semester</th><th>Class</th><th>Score</th><th>Percentage</th><th>Status</th><th>Date</th><th>Actions</th></tr></thead><tbody>${filtered.map(row=>`<tr><td>${esc(row.student.registrationNumber)}</td><td>${esc(row.student.name)}</td><td>${esc(row.student.semester)}</td><td>${esc(row.student.className)}</td><td>${row.result?`${row.result.score}/40`:'—'}</td><td>${row.result?`${row.result.percentage}%`:'—'}</td><td>${esc(row.result?.integrityTerminated?`Terminated (${row.result.integrityWarnings||2} warnings)`:row.student.status||'Registered')}</td><td>${esc(row.date||'—')}</td><td>${row.result?`<button class="btn light" data-view-result="${esc(row.attemptId)}">View</button> <button class="btn danger" data-reset="${esc(row.attemptId)}">Reset</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="9">No student records match this filter.</td></tr>'}</tbody></table></div>`;$$('[data-view-result]').forEach(b=>b.addEventListener('click',()=>{const r=results().find(x=>x.attemptId===b.dataset.viewResult);$('#modal-body').innerHTML=`<h2>${esc(r.student.name)} · ${r.score}/40</h2><p>${esc(r.student.registrationNumber)} · ${esc(r.student.className)} · ${esc(r.student.semester)}</p><p>Correct: ${r.correctCount} · Wrong: ${r.wrongCount} · Unanswered: ${r.unansweredCount} · ${r.percentage}%</p><div class="modal-actions"><button class="btn primary" id="close-result">Close</button></div>`;$('#modal').classList.remove('hidden');$('#close-result').addEventListener('click',()=>$('#modal').classList.add('hidden'))}));$$('[data-reset]').forEach(b=>b.addEventListener('click',()=>resetAttempt(b.dataset.reset)))}
async function resetAttempt(attemptId){const result=results().find(r=>r.attemptId===attemptId);if(!result||!confirm(`Reset this quiz attempt for ${result.student.registrationNumber}? The result will be removed, but the student's registration record will be retained.`))return;if(!isLocalPreviewAdmin()){try{const response=await fetch('/api/results',{method:'DELETE',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({attemptId})}),body=await apiJson(response,'Could not reset this attempt.')}catch(error){alert(error.message||'Could not reset this attempt.');return}}write(KEYS.results,results().filter(r=>r.attemptId!==attemptId));const active=current();if(active?.attemptId===attemptId)write(KEYS.current,null);write(KEYS.students,students().map(s=>s.registrationNumber.toLowerCase()===result.student.registrationNumber.toLowerCase()?{...s,status:'Registered',attemptId:null}:s));renderAdmin()}
function renderClasses(){const rs=results();$('#class-results').innerHTML=CLASSES.map(cls=>{const list=rs.filter(r=>r.student.className===cls).sort((a,b)=>b.score-a.score),top=list.filter(r=>list.filter(x=>x.score>r.score).length<2);return `<section class="class-block"><h2>${cls}</h2><div class="top-list">${top.length?top.map(r=>`<article class="rank-card"><b>Rank ${list.filter(x=>x.score>r.score).length+1} · ${esc(r.student.name)}</b><span>${esc(r.student.registrationNumber)} · ${r.score}/40 · ${r.percentage}%${list.filter(x=>x.score===r.score).length>1?' · tied':''}</span></article>`).join(''):'<article class="rank-card"><span>No completed attempts yet.</span></article>'}</div><div class="student-table-wrap"><table class="student-table"><thead><tr><th>Registration No.</th><th>Name</th><th>Semester</th><th>Score</th><th>Percentage</th><th>Date</th></tr></thead><tbody>${list.map(r=>`<tr><td>${esc(r.student.registrationNumber)}</td><td>${esc(r.student.name)}</td><td>${esc(r.student.semester)}</td><td>${r.score}/40</td><td>${r.percentage}%</td><td>${esc(r.quizDate)}</td></tr>`).join('')||'<tr><td colspan="6">No results</td></tr>'}</tbody></table></div></section>`}).join('')}
const EXPORT_HEADERS=['Registration Number','Student Name','Semester','Class','Correct Answers','Wrong Answers','Unanswered','Score','Total Marks','Percentage','Quiz Date','Start Time','End Time','Time Taken','Status'];
function exportRows(cls){const completed=results().filter(r=>r.student.className===cls),known=new Set(completed.map(r=>r.student.registrationNumber.toLowerCase())),rows=completed.map(r=>[r.student.registrationNumber,r.student.name,r.student.semester,r.student.className,r.correctCount,r.wrongCount,r.unansweredCount,r.score,40,r.percentage,r.quizDate,timeText(r.startTime),timeText(r.endTime),formatDuration(r.timeTakenMs),r.status]);for(const s of students()){if(s.className===cls&&!known.has(s.registrationNumber.toLowerCase()))rows.push([s.registrationNumber,s.name,s.semester,s.className,'','','','',40,'',s.registrationDate||dateText(s.registrationTimestamp),timeText(s.registrationTimestamp),'','',s.status||'Registered'])}return rows}
function exportClass(cls){if(!window.XLSX){alert('Excel library could not load. Connect to the internet once to load SheetJS, then retry.');return}const sheet=XLSX.utils.aoa_to_sheet([EXPORT_HEADERS,...exportRows(cls)]),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,sheet,cls);XLSX.writeFile(wb,`KLE_BCA_Quiz_${cls.replaceAll(' ','_')}.xlsx`)}
