function renderExports(){$('#export-buttons').innerHTML=`<button id="export-all" class="btn primary">Export All Results · XLSX</button>${CLASSES.map((c,i)=>`<button data-export="${i}" class="btn light">Export ${esc(c)}</button>`).join('')}`;$('#export-all').addEventListener('click',exportAll);$$('[data-export]').forEach(b=>b.addEventListener('click',()=>exportClass(CLASSES[Number(b.dataset.export)])))}

const INTEGRITY_WARNING_LIMIT=2;
function trackIntegrityWarning(reason){const quiz=current();if(!quiz||quiz.submitted)return;quiz.integrityWarnings=(quiz.integrityWarnings||0)+1;quiz.lastIntegrityReason=reason;write(KEYS.current,quiz);const warning=$('#integrity-warning');warning.classList.remove('hidden');warning.textContent=quiz.integrityWarnings>=INTEGRITY_WARNING_LIMIT?'Second assessment-rule warning: your attempt is being closed and submitted.':`Warning ${quiz.integrityWarnings} of ${INTEGRITY_WARNING_LIMIT}: ${reason}. A second detected violation will close the assessment.`;if(quiz.integrityWarnings>=INTEGRITY_WARNING_LIMIT){quiz.integrityTerminated=true;quiz.integrityReason=reason;write(KEYS.current,quiz);void submitQuiz()}}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')trackIntegrityWarning('leaving the assessment tab')});
window.addEventListener('keydown',event=>{if(location.hash!=='#quiz'||event.repeat)return;const printScreen=event.key==='PrintScreen'||event.code==='PrintScreen'||event.keyCode===44,macScreenshot=event.metaKey&&event.shiftKey&&['3','4','5'].includes(event.key);if(printScreen||macScreenshot){event.preventDefault();const quiz=current();if(quiz){quiz.lastScreenshotKeyAt=Date.now();write(KEYS.current,quiz)}trackIntegrityWarning('attempting to capture a screenshot')}},true);
window.addEventListener('blur',()=>{setTimeout(()=>{const quiz=current();if(location.hash==='#quiz'&&document.visibilityState!=='hidden'&&Date.now()-(quiz?.lastScreenshotKeyAt||0)>1500)trackIntegrityWarning('assessment window lost focus (possible screenshot or app switch)')},150)});
window.addEventListener('hashchange',()=>{const quiz=current();if(quiz&&!quiz.submitted&&location.hash!=='#quiz'){trackIntegrityWarning('leaving the assessment page');if(!current()?.submitted)showView('quiz')}});

function pdfRows(textContent){const lines=[];for(const item of textContent.items){if(typeof item.str!=='string'||!item.str.trim())continue;const y=Array.isArray(item.transform)?item.transform[5]:0,x=Array.isArray(item.transform)?item.transform[4]:0;let line=lines.find(row=>Math.abs(row.y-y)<2);if(!line){line={y,items:[]};lines.push(line)}line.items.push({x,text:item.str})}return lines.sort((a,b)=>b.y-a.y).map(line=>line.items.sort((a,b)=>a.x-b.x).map(item=>item.text).join(' ').replace(/\s+/g,' ').trim()).filter(Boolean)}
async function loadPdfJs(){if(!pdfJsModulePromise)pdfJsModulePromise=import('../assets/vendor/pdf.min.mjs').then(pdfjs=>{pdfjs.GlobalWorkerOptions.workerSrc=new URL('assets/vendor/pdf.worker.min.mjs',document.baseURI).href;return pdfjs}).catch(error=>{pdfJsModulePromise=null;console.error('PDF reader could not be loaded:',error);throw new Error('The local PDF reader could not be loaded. Refresh the page and retry.')});return pdfJsModulePromise}
async function extractPdfText(file){if(file.size>30*1024*1024)throw new Error(`${file.name} is larger than the 30 MB limit.`);if(!/\.pdf$/i.test(file.name)&&file.type!=='application/pdf')throw new Error(`${file.name} is not a PDF file.`);const pdfjs=await loadPdfJs(),data=new Uint8Array(await file.arrayBuffer()),pdfAssets=new URL('assets/vendor/pdfjs/',document.baseURI).href,documentTask=pdfjs.getDocument({data,cMapUrl:`${pdfAssets}cmaps/`,cMapPacked:true,standardFontDataUrl:`${pdfAssets}standard_fonts/`}),pdf=await documentTask.promise;if(pdf.numPages>200)throw new Error(`${file.name} has more than 200 pages.`);const pages=[];for(let number=1;number<=pdf.numPages;number++){const page=await pdf.getPage(number),content=await page.getTextContent();pages.push(pdfRows(content))}return pages.flat().join('\n')}
function parseAnswerKey(text){const answers=new Map(),lines=text.split(/\r?\n/),pair=/(?:^|[\s,;|])(?:q(?:uestion)?\s*)?(\d{1,3})\s*(?:[).:=\-]\s*|\s+)(?:(?:answer|ans|option)\s*[:.)\-]?\s*)?[\[(]?([A-D])[\])]?(?=$|[\s,;|])/gi;for(let index=0;index<lines.length;index++){const line=lines[index].trim();pair.lastIndex=0;let match;while((match=pair.exec(line))){const number=Number(match[1]);if(number>0&&!answers.has(number))answers.set(number,match[2].toUpperCase())}const numbers=line.match(/\b\d{1,3}\b/g),next=lines[index+1]||'';if(!numbers||numbers.length<2)continue;const letters=next.match(/\b[A-D]\b/gi),numberRemainder=line.replace(/\b\d{1,3}\b/g,'').replace(/[\s,;|.)\[(\]-]/g,'');const answerRemainder=next.replace(/\b[A-D]\b/gi,'').replace(/[\s,;|.)\[(\]-]/g,'');if(letters&&letters.length===numbers.length&&!numberRemainder&&!answerRemainder){for(let i=0;i<numbers.length;i++){const number=Number(numbers[i]);if(number>0&&!answers.has(number))answers.set(number,letters[i].toUpperCase())}}}return answers}
function parseQuestionPdf(text){const answerHeading=/(?:^|\n)\s*(?:(?:official|correct)\s+)?answer\s*key\b[^\n]*/i,answerMatch=answerHeading.exec(text),embeddedAnswers=answerMatch?parseAnswerKey(text.slice(answerMatch.index)):new Map(),questionText=answerMatch?text.slice(0,answerMatch.index):text,lines=questionText.split(/\r?\n/),blocks=[];let active=null;for(const line of lines){const start=line.match(/^\s*(?:question\s*|q\s*)?(\d{1,3})\s*[).:\-]\s*(.*)$/i);if(start){active={number:Number(start[1]),lines:[start[2]]};blocks.push(active)}else if(active)active.lines.push(line)}const parsed=[];for(const block of blocks){const content=block.lines.join(' ').replace(/\s+/g,' ').trim(),marker=/(?:^|\s)(?:\(([A-D])\)|([A-D])[.)])\s*/gi,matches=[];let match;while((match=marker.exec(content)))matches.push({letter:(match[1]||match[2]).toUpperCase(),start:match.index,end:marker.lastIndex});const question=content.slice(0,matches[0]?.start??content.length).trim(),options=matches.map((item,index)=>({letter:item.letter,text:content.slice(item.end,matches[index+1]?.start??content.length).trim()})),letters=new Set(options.map(option=>option.letter));if(question&&options.length===4&&['A','B','C','D'].every(letter=>letters.has(letter))&&options.every(option=>option.text))parsed.push({number:block.number,question,options:options.sort((a,b)=>a.letter.localeCompare(b.letter)),answer:embeddedAnswers.get(block.number)||null})}return{questions:parsed,embeddedAnswers,detectedBlocks:blocks.length}}
function updatePdfImportPreview(){const confirmed=$('#confirm-pdf-import').checked;$('#import-pdf-questions').disabled=importedPdfQuestions.length===0;const answerCount=importedPdfQuestions.filter(q=>q.answer).length;$('#pdf-import-status').classList.remove('hidden');$('#pdf-import-status').className=`notice ${importedPdfQuestions.length?'':'warning'}`;$('#pdf-import-status').textContent=`Detected ${importedPdfQuestions.length} complete four-option questions; answer key matched for ${answerCount}. ${importedPdfQuestions.length?confirmed?'Matched questions will be marked verified after your confirmation.':'Confirm the preview to mark matched answers verified.':'No complete questions detected. Use a text-searchable PDF with numbered questions and A-D options on separate lines.'}`;$('#pdf-import-preview').innerHTML=importedPdfQuestions.map(q=>`<article><b>Q${q.number}${q.answer?` · Answer ${esc(q.answer)}`:' · No answer matched'}</b><p>${esc(q.question)}</p><ol type="A">${q.options.map(option=>`<li>${esc(option.text)}</li>`).join('')}</ol></article>`).join('')}
async function readQuestionPdfs(){const status=$('#pdf-import-status'),questionFile=$('#questions-pdf').files[0],answerFile=$('#answers-pdf').files[0];importedPdfQuestions=[];$('#import-pdf-questions').disabled=true;$('#pdf-import-preview').innerHTML='';if(!questionFile){status.className='notice error';status.textContent='Select a question PDF first.';status.classList.remove('hidden');return}status.className='notice';status.textContent='Reading PDFs locally…';status.classList.remove('hidden');try{const questionPdf=parseQuestionPdf(await extractPdfText(questionFile)),answers=new Map(questionPdf.embeddedAnswers);if(answerFile){for(const [number,answer]of parseAnswerKey(await extractPdfText(answerFile)))answers.set(number,answer)}importedPdfQuestions=questionPdf.questions.map(question=>({...question,answer:answers.get(question.number)||null}));updatePdfImportPreview();if(questionPdf.detectedBlocks!==questionPdf.questions.length)status.textContent+=` ${questionPdf.detectedBlocks-questionPdf.questions.length} numbered blocks did not have a readable question and exactly four A-D options; inspect the source PDF format.`}catch(error){status.className='notice error';status.textContent=error.message||'Could not read the selected PDF.'}}
function importParsedQuestions(){if(!importedPdfQuestions.length)return;const confirmed=$('#confirm-pdf-import').checked,existing=questions();if(existing.length+importedPdfQuestions.length>500){alert('The question bank can contain at most 500 questions.');return}const stamp=Date.now(),added=importedPdfQuestions.map((item,index)=>{const options=item.options.map(option=>({id:`pdf_${stamp}_${index+1}_opt${option.letter}`,text:option.text})),correctOptionId=item.answer?options.find(option=>option.id.endsWith(`_opt${item.answer}`))?.id:null,verified=Boolean(confirmed&&correctOptionId);return{id:`pdf_${stamp}_q${item.number}_${index+1}`,sourceQuestionNumber:item.number,question:item.question,options,correctOptionId:correctOptionId||null,category:'General',image:null,explanation:null,verified,enabled:true,verificationMethod:verified?'PDF extraction reviewed and confirmed by administrator':null}});if(!saveQuestions([...existing,...added]))return;importedPdfQuestions=[];$('#questions-pdf').value='';$('#answers-pdf').value='';$('#confirm-pdf-import').checked=false;$('#pdf-import-preview').innerHTML='';$('#pdf-import-status').className='notice';$('#pdf-import-status').textContent=`Imported ${added.length} questions. ${added.filter(q=>q.verified).length} matched answers marked verified; unmatched questions remain unverified.`;$('#import-pdf-questions').disabled=true;renderAdmin();readiness()}
document.addEventListener('DOMContentLoaded',()=>{$('#parse-pdfs').addEventListener('click',()=>void readQuestionPdfs());$('#confirm-pdf-import').addEventListener('change',updatePdfImportPreview);$('#import-pdf-questions').addEventListener('click',importParsedQuestions)});
const renderCompletedResult=renderResult;renderResult=function(){renderCompletedResult();const quiz=current(),result=results().find(item=>item.attemptId===quiz?.attemptId);if(!result?.integrityTerminated)return;const card=$('.result-card'),actions=$('.result-actions');if(!card||!actions)return;const notice=document.createElement('div');notice.className='notice error integrity-terminated';notice.textContent=`Assessment ended after ${result.integrityWarnings||INTEGRITY_WARNING_LIMIT} detected rule violations. Your attempt has been submitted.`;card.insertBefore(notice,actions)};
const renderStudentRecords=renderStudents;renderStudents=function(){renderStudentRecords();const notice=document.createElement('p');notice.className='muted';notice.textContent='Registered and started students are included. Records do not expire automatically; Reset removes a quiz result but keeps the registration.';$('#student-table').prepend(notice);$$('[data-view-result]').forEach(button=>{const result=results().find(item=>item.attemptId===button.dataset.viewResult);if(result?.integrityTerminated)button.closest('tr').children[6].textContent=`Terminated (${result.integrityWarnings||INTEGRITY_WARNING_LIMIT} warnings)`})};
